begin;

insert into public.stores(
  community_id,name,description,status,store_type,category_group,
  restock_permission
)
select c.id,s.name,s.description,'active',s.store_type,s.category_group,'founder'
from public.communities c
cross join (
  values
    ('Ultimate General Store','Food, clothing, electronics, RP supplies, and general goods.','general','General Store'),
    ('Ultimate Hardware & Auto','Tools, mechanic parts, shop equipment, and vehicle supplies.','general','General Store'),
    ('Ultimate Medical Supply','Medical, rescue, EMS, and first-aid supplies.','general','General Store'),
    ('Ultimate Government Services','Documents, licences, registrations, and government services.','government','Government'),
    ('Ultimate Vehicle Dealership','GTA-style civilian, commercial, marine, and aircraft catalogue.','government','Government'),
    ('Ultimate Property Registry','Apartments, homes, garages, commercial properties, and land.','government','Government'),
    ('Ultimate Licensed Weapons','Licensed fictional GTA-style weapons and defensive equipment.','government','Government')
) s(name,description,store_type,category_group)
on conflict(community_id,name) do update
set description=excluded.description,
    status='active',
    store_type=excluded.store_type,
    category_group=excluded.category_group,
    restock_permission='founder',
    updated_at=now();

