insert into public.store_products(
  community_id,store_id,sku,name,description,category,product_type,
  price,stock_quantity,active,restricted,asset_template,updated_at
)
select
  st.community_id,
  st.id,
  c.sku,
  c.name,
  c.description,
  c.category,
  c.product_type,
  c.price,
  c.stock_quantity,
  true,
  c.restricted,
  c.asset_template,
  now()
from catalogue c
join public.stores st on st.name=c.store_name
on conflict(store_id,sku) do update
set name=excluded.name,
    description=excluded.description,
    category=excluded.category,
    product_type=excluded.product_type,
    price=excluded.price,
    stock_quantity=greatest(public.store_products.stock_quantity,excluded.stock_quantity),
    active=true,
    restricted=excluded.restricted,
    asset_template=excluded.asset_template,
    deleted_at=null,
    updated_at=now();

commit;

select
  st.name as store_name,
  count(sp.id) filter(where sp.active=true) as active_products
from public.stores st
left join public.store_products sp on sp.store_id=st.id
where st.name in (
  'Ultimate General Store',
  'Ultimate Hardware & Auto',
  'Ultimate Medical Supply',
  'Ultimate Government Services',
  'Ultimate Vehicle Dealership',
  'Ultimate Property Registry',
  'Ultimate Licensed Weapons'
)
group by st.name
order by st.name;
